-- =====================================================================
-- CORR-006 Section 4, CX-15 — Section 5.16's corrected text (Annex E)
--
-- GENERATED BY scripts/generate_corr006_s516.py. DO NOT HAND-EDIT.
--
-- WHAT CX-15 SAYS: "Replace the two sentences of Section 5.16 set out in
-- Annex E... Render the corrected text; the old sentences must no longer
-- render anywhere."
--
-- WHAT MEASURING FOUND, AND IT CHANGES WHAT "REPLACE" CAN MEAN HERE.
--
-- The retired sentences render NOWHERE. Searched before writing anything:
--
--     the phrase "artificial intelligence"   0 occurrences in src/,
--                                            supabase/migrations/ and in
--                                            every loaded content version
--     the string "5.16"                      0 occurrences in either
--     T3A-D1-EXEC-001 Section 5.16           not on disk and never loaded
--
-- So there is no participant notice to edit. The Section 5.16 wording that
-- tells every participant how a Stage is administered was never built, and
-- "the old sentences must no longer render anywhere" is TRUE TODAY BECAUSE
-- NOTHING RENDERS AT ALL. That is not the same as having replaced them, and
-- reporting CX-15 as "replaced" would be a false statement about
-- participant-facing text.
--
-- WHAT IS DONE INSTEAD, which is the durable half of the instruction:
--
--   1. The corrected text loads as issued content, so when the notice is
--      built there is one approved wording for it to render and no reason
--      for anyone to retype the old one from T3A-D1-EXEC-001.
--   2. Both retired sentences are recorded as RETIRED, with their hashes,
--      and a guard refuses to store any participant notice containing
--      either of them. "Must no longer render anywhere" then survives the
--      notice being built later by someone reading the superseded document.
--
-- Internal identifiers containing "AI" are NOT renamed (CX-15, and Standing
-- Rule 4): t3a_d1_ai_administration_run and its columns are untouched.
-- =====================================================================

set search_path = public;

-- ---------------------------------------------------------------------
-- 1. The retired sentences, as rows, so the guard has something to read
-- ---------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS public.t3a_retired_participant_sentence (
  sentence_hash   text PRIMARY KEY,
  retired_text    text NOT NULL,
  replaced_by     text NOT NULL,
  retired_under   text NOT NULL,
  why             text NOT NULL
);

COMMENT ON TABLE public.t3a_retired_participant_sentence IS
  'CX-15. Participant-facing sentences that must no longer render anywhere, with what replaced them. Held as rows so the refusal reads a register rather than matching a pattern, and so a later instrument can retire another sentence without a code change. Keyed by the sha256 of the retired text.';

