   'Stage 1 is administered by a deterministic delivery engine and no generative model is used (CORR-006 Section 4.1), so the sentence told every participant something untrue about how they were being assessed.')
ON CONFLICT (sentence_hash) DO UPDATE SET
  retired_text = EXCLUDED.retired_text, replaced_by = EXCLUDED.replaced_by,
  retired_under = EXCLUDED.retired_under, why = EXCLUDED.why;

ALTER TABLE public.t3a_retired_participant_sentence ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS t3a_retired_participant_sentence_read ON public.t3a_retired_participant_sentence;
CREATE POLICY t3a_retired_participant_sentence_read
  ON public.t3a_retired_participant_sentence FOR SELECT TO authenticated USING (true);

-- ---------------------------------------------------------------------
-- 2. The corrected text, as issued content
--
-- Two judgment calls here, both recorded in the register rather than
-- presented as the founder's.
--
--   The IDENTIFIER is the build's: the instrument names Annexes A, B and C
--   and does not name Annex E, and content is registered by identifier.
--
--   The FAMILY is 'configuration'. t3a_content_family has no
--   participant_notice value, and adding one would define a new class of
--   content in the schema's vocabulary — a doctrine act, which the
--   DEVELOPER JUDGMENT BOUNDARY reserves. Annex C is the precedent: the
--   Participant Safety Configuration is a configuration and carries the
--   crisis line a participant reads.
-- ---------------------------------------------------------------------

DO $load$
DECLARE v_obj uuid;
BEGIN
  SELECT content_object_id INTO v_obj FROM public.t3a_content_object
   WHERE identifier = 'T3A-D1-S516-PARTICIPANT-NOTICE-001';

  IF v_obj IS NULL THEN
    INSERT INTO public.t3a_content_object (identifier, family, title, dimension_id)
    VALUES ('T3A-D1-S516-PARTICIPANT-NOTICE-001',
            -- 'configuration', because t3a_content_family has no
            -- participant_notice value and adding one would define a new
            -- CLASS of content in the schema's vocabulary. Annex C is
            -- precedent: the Participant Safety Configuration is a
            -- configuration and carries the crisis line a participant reads.
            'configuration'::public.t3a_content_family,
            'Section 5.16, corrected text', 'D1')
    RETURNING content_object_id INTO v_obj;
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.t3a_d1_content_version
                  WHERE content_object_id = v_obj AND superseded_by IS NULL) THEN
    INSERT INTO public.t3a_d1_content_version (content_object_id, version_no, body)
    VALUES (v_obj, 1, jsonb_build_object(
      'source_identifier', 'T3A-D1-S516-PARTICIPANT-NOTICE-001',
      'title', 'Section 5.16, corrected text',
      'issued_under', 'T3A-D1-EXEC-CORR-006 Annex E',
      'amends', 'T3A-D1-EXEC-001 Section 5.16 — two sentences; everything else in Section 5.16 is unchanged',
      'verbatim', 'Some are presented to you on screen by an automated system.

Where an automated system is used, it shows you the situation in fixed stages, exactly as written, and keeps your responses exactly as you typed them. It does not write, change or judge anything, and nobody reads your responses while you are typing them. An authorized person reads them afterwards and is accountable for what enters your record. The automated system does not decide what your record says, does not issue your report, and does not decide a correction.',
      'source_version_hash', 'b58a248fe9d2f8dd0c5d20871b3d3d5742f780e60e9859f2bb187a99d37601b9',
      'sentences', jsonb_build_array(
        jsonb_build_object('replaces', 'Some are administered using artificial intelligence.', 'replaces_hash', '7d759908007b3637b50bd048e66a152db886bac72505e745cf9e8510ca30c55c', 'text', 'Some are presented to you on screen by an automated system.', 'text_hash', '83d55d01797bbae3b3075244f2ff99c80545ce843774a1e6c537868f565f388e'),
        jsonb_build_object('replaces', 'Where artificial intelligence is used, it presents the situation and organizes what happened. An authorized person is accountable for what enters your record. Artificial intelligence does not decide what your record says, does not issue your report, and does not decide a correction.', 'replaces_hash', '4509d29e2419316807001f043c6833433534062464f392db35cc4eae89619379', 'text', 'Where an automated system is used, it shows you the situation in fixed stages, exactly as written, and keeps your responses exactly as you typed them. It does not write, change or judge anything, and nobody reads your responses while you are typing them. An authorized person reads them afterwards and is accountable for what enters your record. The automated system does not decide what your record says, does not issue your report, and does not decide a correction.', 'text_hash', '7d11334a837759d0cff7b795c82030306c983d7cab1ce5c60a5b03e51ab410eb'))));
  END IF;
END;
$load$;

-- ---------------------------------------------------------------------
-- 3. The refusal, so "no longer render anywhere" survives the notice being
--    built later from the superseded document
-- ---------------------------------------------------------------------

CREATE OR REPLACE FUNCTION public.t3a_participant_notice_carries_no_retired_sentence()
RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE
  v_hit text;
BEGIN
  -- SCOPED TO EVERY CONTENT VERSION, deliberately, and this is the most
  -- restrictive of the readings available.
  --
  -- The narrower guard would apply only to a participant-facing family. But
  -- there is no such family, and a body flag the author has to remember to
  -- set is a guard that misses exactly the case it exists for — someone
  -- rebuilding the notice from the superseded T3A-D1-EXEC-001.
  --
  -- A blanket guard is safe here because it was MEASURED to be: zero loaded
  -- content versions contain either retired sentence today, so nothing
  -- already stored becomes unwritable. The cost is that a governance
  -- document QUOTING a retired sentence in order to retire it could not be
  -- loaded as content. CORR-006 is such a document and is not loaded as
  -- content, so nothing is blocked now; if that day comes, the exemption is
  -- a governance decision and belongs in an instrument rather than in a
  -- flag a build invents in advance.
  SELECT s.retired_text INTO v_hit
    FROM public.t3a_retired_participant_sentence s
   WHERE position(s.retired_text in coalesce(NEW.body ->> 'verbatim', '')) > 0
   LIMIT 1;

  IF v_hit IS NOT NULL THEN
    RAISE EXCEPTION 'PARTICIPANT_NOTICE_CARRIES_RETIRED_SENTENCE: the text contains "%" which was retired under CORR-006 Annex E. Use the replacement recorded beside it in t3a_retired_participant_sentence.', v_hit
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$fn$;

COMMENT ON FUNCTION public.t3a_participant_notice_carries_no_retired_sentence() IS
  'CX-15. Refuses ANY content version containing a retired participant sentence, by name, reading t3a_retired_participant_sentence. Blanket rather than scoped to a family because no participant-facing family exists and a body flag would be forgotten by exactly the author this guards against. Measured safe: zero loaded versions contain either sentence. A governance document quoting a retired sentence in order to retire it would be refused; CORR-006 is not loaded as content, and exempting one is a governance decision for an instrument, not a flag a build invents in advance.';

DROP TRIGGER IF EXISTS t3a_participant_notice_retired_sentence_trg
  ON public.t3a_d1_content_version;
CREATE TRIGGER t3a_participant_notice_retired_sentence_trg
  BEFORE INSERT OR UPDATE ON public.t3a_d1_content_version
  FOR EACH ROW EXECUTE FUNCTION public.t3a_participant_notice_carries_no_retired_sentence();

-- ---------------------------------------------------------------------
-- 4. Assert, from what was stored
-- ---------------------------------------------------------------------

DO $verify$
DECLARE
  v_n       int;
  v_body    jsonb;
  v_stored  text;
  s         jsonb;
BEGIN
  SELECT count(*) INTO v_n FROM public.t3a_retired_participant_sentence;
  IF v_n <> 2 THEN
    RAISE EXCEPTION 'CX15_WRONG_COUNT: % retired sentences, and Annex E replaces exactly two.', v_n;
  END IF;

  -- Each retired row's key must be the hash of its own text.
  IF EXISTS (SELECT 1 FROM public.t3a_retired_participant_sentence s
              WHERE encode(sha256(convert_to(s.retired_text, 'UTF8')), 'hex') <> s.sentence_hash) THEN
    RAISE EXCEPTION 'CX15_RETIRED_TEXT_DRIFTED: a retired sentence does not hash to its own key.';
  END IF;

  SELECT cv.body INTO v_body
    FROM public.t3a_content_object co
    JOIN public.t3a_d1_content_version cv
      ON cv.content_object_id = co.content_object_id AND cv.superseded_by IS NULL
   WHERE co.identifier = 'T3A-D1-S516-PARTICIPANT-NOTICE-001';

  IF v_body IS NULL THEN
    RAISE EXCEPTION 'CX15_NOTICE_NOT_LOADED: the corrected Section 5.16 text is not loaded.';
  END IF;

  v_stored := v_body ->> 'verbatim';
  IF encode(sha256(convert_to(v_stored, 'UTF8')), 'hex') IS DISTINCT FROM (v_body ->> 'source_version_hash') THEN
    RAISE EXCEPTION 'CX15_NOTICE_DRIFTED: the stored corrected text does not hash to its stored hash.';
  END IF;

  FOR s IN SELECT x FROM jsonb_array_elements(v_body -> 'sentences') x LOOP
    IF encode(sha256(convert_to(s ->> 'text', 'UTF8')), 'hex') IS DISTINCT FROM (s ->> 'text_hash') THEN
      RAISE EXCEPTION 'CX15_SENTENCE_DRIFTED: a corrected sentence does not hash to its stored hash.';
    END IF;
    -- The corrected wording must not itself contain what it replaces.
    IF position((s ->> 'replaces') in (s ->> 'text')) > 0 THEN
      RAISE EXCEPTION 'CX15_REPLACEMENT_CONTAINS_WHAT_IT_REPLACES.';
    END IF;
  END LOOP;

  -- And the corrected notice really did load, which means the trigger above
  -- did not refuse it — the negative control for the guard.
  RAISE NOTICE 'CX-15: two sentences retired with their hashes, the corrected notice loaded and self-consistent, and the guard admitted it.';
END;
$verify$;

